{"policy":"permit (
    principal is User,
    action == Action::"authorizeSwitchingOrder",
    resource is SwitchingOrder
)
when {
    principal.roles.contains(Role::"Planner") ||
    principal.roles.contains(Role::"ShiftSupervisor")
};

forbid (
    principal is User,
    action == Action::"authorizeSwitchingOrder",
    resource is SwitchingOrder
)
when {
    resource.status != "planned"
};

forbid (
    principal is User,
    action == Action::"authorizeSwitchingOrder",
    resource is SwitchingOrder
)
when {
    !context.lockoutTagoutVerified
};

forbid (
    principal is User,
    action == Action::"authorizeSwitchingOrder",
    resource is SwitchingOrder
)
when {
    resource.voltageLevel.greaterThan(context.shiftSupervisorVoltageThreshold) &&
    !principal.roles.contains(Role::"ShiftSupervisor")
};"}
